# owner: platform
"""Snap span times to a payroll step, then label them."""

from typing import Iterable, List

from hourglass.parsing import format_span
from hourglass.models import Span


def _check_step(step: int) -> None:
    if step <= 0 or 60 % step:
        raise ValueError(
            f"step must divide an hour evenly: {step}"
        )


def _snap(value: int, step: int) -> int:
    """Nearest multiple of step, with halves going up."""
    return (2 * value + step) // (2 * step) * step


def _label(span: Span) -> str:
    hours, rest = divmod(span.minutes, 60)
    return f"{format_span(span)} ({hours}h {rest}m)"


# ---
def round_labels(
    spans: Iterable[Span], step: int
) -> List[str]:
    """Labels like 09:00-17:15 (8h 15m), one per span.

    A span that shrinks to nothing raises ValueError.
    """
    _check_step(step)
    labels = []
    for span in spans:
        start = _snap(span.start, step)
        end = _snap(span.end, step)
        labels.append(_label(Span(start, end)))
    return labels

