# owner: platform
import unittest

from hourglass.rounding import round_labels
from hourglass.parsing import parse_span


def labels_for(text: str, step: int) -> list:
    return round_labels([parse_span(text)], step)


class RoundLabelTests(unittest.TestCase):
    def test_label_format(self):
        got = labels_for("09:00-17:15", 15)
        self.assertEqual(got, ["09:00-17:15 (8h 15m)"])

    def test_rounds_to_nearest(self):
        got = labels_for("09:07-17:08", 15)
        self.assertEqual(got, ["09:00-17:15 (8h 15m)"])

    def test_halves_round_up(self):
        got = labels_for("09:07-10:22", 15)
        self.assertEqual(got, ["09:00-10:15 (1h 15m)"])

    def test_many_spans_in_order(self):
        spans = [parse_span("08:58-12:01")]
        spans.append(parse_span("13:00-14:00"))
        got = round_labels(spans, 30)
        self.assertEqual(
            got,
            ["09:00-12:00 (3h 0m)", "13:00-14:00 (1h 0m)"]
        )

    def test_empty(self):
        self.assertEqual(round_labels([], 15), [])

    def test_end_of_day(self):
        got = labels_for("23:00-24:00", 60)
        self.assertEqual(got, ["23:00-24:00 (1h 0m)"])

    def test_bad_steps_raise(self):
        for step in (0, -15, 7, 45, 120):
            with self.subTest(step=step):
                with self.assertRaises(ValueError):
                    labels_for("09:00-10:00", step)

    def test_bad_step_raises_for_no_spans(self):
        with self.assertRaises(ValueError):
            round_labels([], 0)

    def test_collapsed_span_raises(self):
        with self.assertRaises(ValueError):
            labels_for("09:01-09:04", 15)
